def transform(g):
    H,W=len(g),len(g[0])
    Sp=[(i,j) for i,r in enumerate(g) for j,v in enumerate(r) if v not in (0,1) and v==max(set(x for r in g for x in r)-{0,1}, key=lambda c: 0) ] if False else [(i,j) for i,r in enumerate(g) for j,v in enumerate(r) if v not in (0,1)]
    sc=[v for i,j in Sp][0]
    bi,bj=min(Sp); rel=[(i-bi,j-bj) for i,j in Sp]
    out=[row[:] for row in g]
    for di in range(H):
        for dj in range(-W,W):
            cells=[(bi+di+r,bj+dj+c) for r,c in rel]
            if all(0<=i<H and 0<=j<W for i,j in cells):
                vals={g[i][j] for i,j in cells}
                if len(vals)==1 and vals!={sc}:
                    for i,j in cells: out[i][j]=sc
    return out
