def gen(g):
    H,W=len(g),len(g[0])
    cnt=Counter(v for r in g for v in r); sc=cnt.most_common()[-1][0]
    Sp=[(i,j) for i,r in enumerate(g) for j,v in enumerate(r) if v==sc]
    b=min(Sp); rel=[(i-b[0],j-b[1]) for i,j in Sp]
    out=[]
    for di in range(H):
        for dj in range(-W,W):
            cells=[(b[0]+di+r,b[1]+dj+c) for r,c in rel]
            if all(0<=i<H and 0<=j<W for i,j in cells):
                vals=[g[i][j] for i,j in cells]
                out.append(((di,dj),cells,set(vals)))
    return sc,rel,out
def stampcheck(g,o,label):
    sc,rel,pl=gen(g)
    S={(i,j) for i,r in enumerate(g) for j,v in enumerate(r) if v==sc}
    A={(i,j) for i,r in enumerate(o) for j,v in enumerate(r) if v==sc}
    add=A-S
    st=[p for p in pl if set(p[1])<=add and set(p[1]) and all(o[i][j]==sc for i,j in p[1])]
    print(label,"sc=",sc,"placements colors:",Counter(frozenset(p[2]) for p in pl))
    print(label,"stamped:",[p[0] for p in st])
