def fits_clip(g, rel, allow='clip'):
    H,W=len(g),len(g[0])
    res=[]
    for di in range(-3,H+3):
        for dj in range(-6,W+6):
            cs=[(di+a,dj+b) for a,b in rel]
            ib=[(i,j) for i,j in cs if 0<=i<H and 0<=j<W]
            if not ib: continue
            if all(g[i][j]==0 for i,j in ib):
                oob=len(cs)-len(ib)
                if allow=='clip' or True:
                    res.append(((di,dj),oob))
    return res
